m_ledgerstep_TurnEnd.signature:
// TurnEnd 是等待层观察到的一次回合终态事实：事件类型、事件序号与失败分类。
//
// 为什么不能只返回 error：下游要按结构化字段判断「这是不是一次明确的零文本
// 故障」，把它压成裸字符串就等于逼消费方回去解析 fail_reason 散文（B100 禁止）。
// FailureClass 只从 turn_failed payload 的精确字段取，空/未知一律零值。
type TurnEnd struct {
	EventType    proto.EventType
	Seq          int64
	FailureClass proto.FailureClass
}

n_ledgerstep_failureClassOf.signature:
// failureClassOf 只从 turn_failed 事件 payload 里取封闭分类；failed 事件与
// 缺字段、未知值一律返回零值（不可自动重试）。
func failureClassOf(event *proto.Event) proto.FailureClass {
	if event == nil || event.Type != proto.EventTypeTurnFailed {
		return ""
	}
	var payload failedPayload
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return ""
	}
	return payload.FailureClass
}

m_executor_Result.signature:
// Result 是一次执行回合的终态结果（OK 或 FailReason 二选一）。
type Result struct {
	Branch     string // executor 工作分支名（如 handoff/T1）
	CommitHash string // 回合收尾 commit 的哈希
	SessionID  string // executor 会话标识（如 opencode session id），供续接与归档
	Summary    string // 执行摘要（给协调者看的完成说明）
	// FinalText 是回合末正文的尾部窗口。它与 Summary 分开传递，因为裁决块
	// 属于正文而不是 trailer 摘要；adapter 只保留正文尾部，以便在结果 payload
	// 有界时仍保全契约要求位于报文末尾的 handoff-verdict block。
	FinalText  string
	OK         bool   // true=正常完成；false=失败（见 FailReason）
	FailReason string // OK=false 时的失败原因/日志尾部
	// FailureClass 是 OK=false 时的封闭失败分类（proto.FailureClass）。
	// 空=未分类：旧 adapter 与绝大多数失败路径不填，消费方按「不可自动重试」
	// 处置。只有 adapter 的明确零文本分支写 proto.FailureClassZeroText。
	FailureClass proto.FailureClass
	// VoidReason 是本次失败导致挂起工单被作废时写进审计事件的理由。
	// 空表示沿用缺省 VoidReasonExecutorGone——绝大多数失败路径（进程退出、
	// 看门狗判死）确实是 executor 没了，不必逐个填。
	VoidReason string
}

m_orchestration_FailedPayload.signature:
// FailedPayload 是 failed 事件的 payload。
type FailedPayload struct {
	FailReason string `json:"fail_reason"`
	// FailureClass 是 additiv、omitempty 的封闭失败分类（B402）。空=未分类，
	// 旧 wire 形状不变；只有 executor 明确零文本分支才会带 zero_text。
	// 消费方只认精确值，未知值一律 fail-closed，不得从 FailReason 反推。
	FailureClass proto.FailureClass `json:"failure_class,omitempty"`
	// Branch/CommitHash 为 omitempty：绝大多数 failed（executor 崩溃、看门狗
	// 判死）没有 git 实况，让空字段出现在 payload 里会让下游以为「查过 git 且
	// 分支是空」。只有回合纪律类失败（无 trailer 但有新提交）才带这两个字段——
	// 它们是协调者判断「这回合到底干到哪儿」的唯一结构化依据，降级成 FailReason
	// 里的一段自由文本就没法再结构化取用了。
	Branch     string `json:"branch,omitempty"`
	CommitHash string `json:"commit,omitempty"`
	// ProcUsage 是任务失败时刻的进程占用快照；读不出数时为 nil。
	//
	// 为什么用指针 + omitempty 而不是零值：一个「0/0」的快照会被读成
	// 「死亡时机器很空闲」，那是彻头彻尾的谎话，比没有快照更糟。nil 表示
	// 「没测到」，与「测到了，很空闲」是两件事，必须能区分
	ProcUsage *prochost.Admission `json:"proc_usage,omitempty"`
}

n_orchestration_NewFailedPayload.signature:
// NewFailedPayload 构造带占用快照的失败载荷。
//
// 参数：reason 为失败原因，原样保留不做改写；branch/commit 为可选的 git 实况，
// 绝大多数失败路径没有（进程退出、对账），传空串即可；class 为封闭失败分类，
// 未分类传空串——只有回合零文本失败才传 proto.FailureClassZeroText。
func NewFailedPayload(reason, branch, commit string, class proto.FailureClass) FailedPayload {
	p := FailedPayload{FailReason: reason, Branch: branch, CommitHash: commit, FailureClass: class}
	if a := admissionFn(); a.Known {
		p.ProcUsage = &a
	}
	return p
}

n_ledgerstep_waitForTurnEnd.signature:
// waitForTurnEnd 反复 wait 直到收到带正文的 completed、真实失败终态，
// 或 task 归档（archived，B396），中途的权限门与工单一律跳过继续等。
//
// why 要循环：WaitEvent 返回的是「首个可动作事件」而非终态。审阅虽只跑
// 只读命令，但同样要过权限门，也可能发工单——2026-08-19 真机实测，环节
// 几乎必然醒在 permission_request/question 上，随即去取最终报文，报
// 「事件流中没有 completed/failed 最终报文」，一轮审阅白跑。函数头写的
// 「wait 终态」是意图，WaitEvent 的语义不是，这里补上差额。
//
// 收到缺正文的 completed 后，后续 wait 使用秒级 child deadline 给迟到正文机会；
// deadline 到期且 parent 仍存活时返回成功，由 Attach 快照回落摘要。
func waitForTurnEnd(ctx context.Context, wait func(context.Context) (*proto.Event, error)) (TurnEnd, error) {
	for {
		event, err := wait(ctx)
		if err != nil {
			slog.ErrorContext(ctx, "等待回合终态失败", "saw_completed", false, "error", err)
			return TurnEnd{}, err
		}
		if event == nil {
			slog.WarnContext(ctx, "等待回合终态收到空事件")
			continue
		}
		switch event.Type {
		case proto.EventTypeArchived:
			// B396：task 已被归档（外部 done/resume --force 后再 done），此后不会
			// 再产出 completed/failed 裁决报文。继续等只会把运行锁与卡节点槽位
			// 钉死，使同卡同节点永远 409。收口为可行动错误，由上游落等人标记。
			slog.WarnContext(ctx, "等待的 task 已归档，回合不会再有终态报文",
				"seq", event.Seq, "task", event.TaskID, "cause", errTurnArchived)
			return TurnEnd{}, errTurnArchived
		case proto.EventTypeCompleted:
			payload, decodeErr := decodeCompletedPayload(event)
			if decodeErr != nil {
				slog.WarnContext(ctx, "completed payload 不可解析，进入宽限", "error", decodeErr)
			} else if payload.FinalText != nil && *payload.FinalText != "" {
				slog.InfoContext(ctx, "收到带 final_text 的 completed")
				return TurnEnd{EventType: proto.EventTypeCompleted, Seq: event.Seq}, nil
			} else {
				finalTextPresent := payload.FinalText != nil
				slog.InfoContext(ctx, "收到残缺 completed，进入宽限", "final_text_present", finalTextPresent)
			}
			return waitForTurnEndGrace(ctx, wait, TurnEnd{EventType: proto.EventTypeCompleted, Seq: event.Seq})
		case proto.EventTypeTurnFailed, proto.EventTypeFailed:
			class := failureClassOf(event)
			slog.InfoContext(ctx, "未见 completed，失败事件收口",
				"event_type", event.Type, "failure_class", class)
			return TurnEnd{
				EventType:    event.Type,
				Seq:          event.Seq,
				FailureClass: class,
			}, nil
		}
	}
}

n_ledgerstep_waitForTurnEndGrace.signature:
// waitForTurnEndGrace 在收到缺正文的 completed 后，用秒级 child deadline 给迟到
// 正文一次机会；到期且 parent 仍存活时返回已观察到的 completed 终态（seq 来自
// 首个 completed），由 Attach 快照回落摘要。
func waitForTurnEndGrace(ctx context.Context, wait func(context.Context) (*proto.Event, error), completed TurnEnd) (TurnEnd, error) {
	waitCtx, cancel := context.WithTimeout(ctx, turnEndGrace)
	defer cancel()
	for {
		event, err := wait(waitCtx)
		if err != nil {
			if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
				slog.InfoContext(ctx, "completed 宽限到期，继续收取 Attach 摘要")
				return completed, nil
			}
			slog.ErrorContext(ctx, "等待回合终态失败", "saw_completed", true, "error", err)
			return TurnEnd{}, err
		}
		if event == nil {
			slog.WarnContext(ctx, "等待回合终态收到空事件")
			continue
		}
		if event.Type == proto.EventTypeCompleted {
			payload, decodeErr := decodeCompletedPayload(event)
			if decodeErr != nil {
				slog.WarnContext(ctx, "宽限内 completed payload 不可解析，继续等待", "error", decodeErr)
				continue
			}
			if payload.FinalText != nil && *payload.FinalText != "" {
				slog.InfoContext(ctx, "宽限内收到带 final_text 的 completed")
				return TurnEnd{EventType: proto.EventTypeCompleted, Seq: event.Seq}, nil
			}
			slog.InfoContext(ctx, "宽限内收到残缺 completed，继续等待", "final_text_present", payload.FinalText != nil)
			continue
		}
		if event.Type == proto.EventTypeArchived {
			slog.WarnContext(ctx, "宽限期内 task 已归档，回合不会再有终态报文",
				"seq", event.Seq, "task", event.TaskID, "cause", errTurnArchived)
			return TurnEnd{}, errTurnArchived
		}
		if event.Type == proto.EventTypeTurnFailed || event.Type == proto.EventTypeFailed {
			slog.InfoContext(ctx, "宽限内忽略失败事件，继续等待 completed", "event_type", event.Type)
		}
	}
}

n_ledgerstep_StepRunner_awaitNode.signature:
// awaitNode 生产 NodeStep.Await：等回合终态并取最终报文。归档在 FinishTask，
// 必须排在 PublishWorkBranch 之后。
//
// 自动续接边界（spec §4.2）：首个终态若是 turn_failed 且分类精确为 zero_text，
// 复用既有 client.Continue 向同一 task 续接恰一次，再等第二个终态；第二个终态
// 才交给节点裁决。续接失败、外部已抢先续接（409）一律 fail-closed 返回错误，
// 由上游落等人，绝不归档。
func (r *StepRunner) awaitNode() func(context.Context, string, string) (string, error) {
	return func(ctx context.Context, target, taskID string) (string, error) {
		logger := slog.Default().With("target", target, "task", taskID)
		logger.Info("节点等待开始")
		if r.Clients == nil {
			err := fmt.Errorf("节点等待客户端未装配")
			logger.Warn("取得节点等待客户端失败", "cause", err)
			return "", err
		}
		cl, err := r.Clients(target)
		if err != nil {
			logger.Warn("取得节点等待客户端失败", "cause", err)
			return "", err
		}
		// 本机任务仍走正式 /ws/events；任务镜像已跳过本机，不会再次 Publish
		// 同一事件。这样节点等待、CLI wait 与远端任务继续共用同一协议。
		logger.Info("节点等待客户端已就绪")
		end, err := waitForTurnEnd(ctx, func(ctx context.Context) (*proto.Event, error) {
			return cl.WaitEvent(ctx, taskID, false)
		})
		if err != nil {
			logger.Warn("节点等待终态失败", "cause", err)
			return "", fmt.Errorf("等回合终态: %w", err)
		}
		if end.EventType == proto.EventTypeTurnFailed && end.FailureClass == proto.FailureClassZeroText {
			logger.Warn("首回合零文本失败，自动续接一次", "task", taskID, "seq", end.Seq)
			if contErr := cl.Continue(ctx, taskID, ZeroTextContinueInstruction); contErr != nil {
				logger.Warn("零文本自动续接失败，fail-closed", "task", taskID, "cause", contErr)
				return "", fmt.Errorf("零文本自动续接: %w", contErr)
			}
			end, err = waitForTurnEnd(ctx, func(ctx context.Context) (*proto.Event, error) {
				return cl.WaitEvent(ctx, taskID, false)
			})
			if err != nil {
				logger.Warn("续接后等待终态失败", "cause", err)
				return "", fmt.Errorf("等回合终态（续接后）: %w", err)
			}
			logger.Info("零文本自动续接后收到终态",
				"task", taskID, "event_type", end.EventType,
				"failure_class", end.FailureClass, "seq", end.Seq)
		}
		message, err := clientFinalMessage(ctx, cl, taskID)
		if err != nil {
			logger.Warn("节点读取最终报文失败", "cause", err)
			return "", err
		}
		logger.Info("节点等待完成", "message_bytes", len(message))
		return message, nil
	}
}
